// view_matrix is a row-major 4x4 flattened as float[16].
// column 3 is translation; row 3 holds the perspective divisor.
inline bool world_to_screen(const Vec3& w, const float m[16], Vec2& out, int width, int height) {
    float wdiv = m[3]*w.x + m[7]*w.y + m[11]*w.z + m[15];
    if (wdiv < 0.01f) return false;
    float nx = (m[0]*w.x + m[4]*w.y + m[8]*w.z  + m[12]) / wdiv;
    float ny = (m[1]*w.x + m[5]*w.y + m[9]*w.z  + m[13]) / wdiv;
    out.x = (width  * 0.5f) + (nx * width  * 0.5f);
    out.y = (height * 0.5f) - (ny * height * 0.5f);
    return true;
}

