    bool attach(const wchar_t* processName, const wchar_t* moduleName) {
        pid = findPid(processName);
        if (!pid) return false;
        hProc = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!hProc) return false;
        base = moduleBase(moduleName);
        return base != 0;
    }

    ~Memory() { if (hProc) CloseHandle(hProc); }

    template <typename T>
    T read(uintptr_t addr) const {
        T v{};
        SIZE_T n = 0;
        if (!ReadProcessMemory(hProc, reinterpret_cast<LPCVOID>(addr), &v, sizeof(T), &n) || n != sizeof(T))
            return T{};
        return v;
    }

    bool readRaw(uintptr_t addr, void* out, size_t size) const {
        SIZE_T n = 0;
        return ReadProcessMemory(hProc, reinterpret_cast<LPCVOID>(addr), out, size, &n) && n == size;
    }

    // Follow a pointer chain: read<T>(*(*(base+o0)+o1)+o2 ...)
    template <typename T>
    T readChain(uintptr_t addr, std::initializer_list<uintptr_t> offsets) const {
        uintptr_t p = addr;
        for (auto it = offsets.begin(); it != offsets.end(); ++it) {
            auto next = std::next(it);
            if (next == offsets.end())
                return read<T>(p + *it);
            p = read<uintptr_t>(p + *it);
            if (!p) return T{};
        }
        return T{};
    }

    uintptr_t moduleBase(const wchar_t* name) const {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        if (snap == INVALID_HANDLE_VALUE) return 0;
