    SOCKET sock;
    HANDLE hToChild;    /* padre escribe -> stdin del hijo   */
    HANDLE hFromChild;  /* padre lee     <- stdout/stderr    */
    HANDLE hProc;
    HANDLE hThread;
} session_t;

/* ---------------------------------------------------------------- utils */

static int send_all(SOCKET s, const char *buf, int len)
{
    int off = 0;
    while (off < len) {
        int n = send(s, buf + off, len - off, 0);
        if (n <= 0) return -1;
        off += n;
    }
    return 0;
}

/* conecta con timeout, resolviendo nombre o IP */
static SOCKET dial(const char *host, const char *port, int timeout_ms)
{
    struct addrinfo hints, *res = NULL, *ai;
    SOCKET s = INVALID_SOCKET;
    u_long nb;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family   = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    if (getaddrinfo(host, port, &hints, &res) != 0)
        return INVALID_SOCKET;

    for (ai = res; ai; ai = ai->ai_next) {
        s = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
        if (s == INVALID_SOCKET) continue;

        nb = 1;
        ioctlsocket(s, FIONBIO, &nb);

        if (connect(s, ai->ai_addr, (int)ai->ai_addrlen) == 0) {
            /* conexión inmediata */
        } else if (WSAGetLastError() == WSAEWOULDBLOCK) {
            fd_set wfds, efds;
            struct timeval tv;
            int err = 0, len = sizeof(err);

            FD_ZERO(&wfds); FD_SET(s, &wfds);
            FD_ZERO(&efds); FD_SET(s, &efds);
            tv.tv_sec  = timeout_ms / 1000;
            tv.tv_usec = (timeout_ms % 1000) * 1000;

            if (select(0, NULL, &wfds, &efds, &tv) <= 0) {
                closesocket(s); s = INVALID_SOCKET; continue;
            }
            if (getsockopt(s, SOL_SOCKET, SO_ERROR, (char *)&err, &len) != 0 || err != 0) {
                closesocket(s); s = INVALID_SOCKET; continue;
            }
        } else {
            closesocket(s); s = INVALID_SOCKET; continue;
        }

        nb = 0;
        ioctlsocket(s, FIONBIO, &nb);
        break;
    }

    freeaddrinfo(res);
    return s;
}

/* ------------------------------------------------------- bombeo de datos */

/* socket -> stdin del hijo. Al salir rompe la otra dirección. */
static DWORD WINAPI pump_to_child(LPVOID param)
{
    session_t *s = (session_t *)param;
    char buf[BUFSZ];
    DWORD wr;

    for (;;) {
        int n = recv(s->sock, buf, BUFSZ, 0);
        if (n <= 0) break;
        if (!WriteFile(s->hToChild, buf, (DWORD)n, &wr, NULL) || wr != (DWORD)n)
            break;
    }

    /* desbloquea pump_from_child si está en send() */
    shutdown(s->sock, SD_BOTH);
    return 0;
}

/* stdout/stderr del hijo -> socket. Retorna al morir cualquiera de los dos. */
static void pump_from_child(session_t *s)
{
    char buf[BUFSZ];
    DWORD rd;

    for (;;) {
        if (!ReadFile(s->hFromChild, buf, BUFSZ, &rd, NULL) || rd == 0)
            return;
        if (send_all(s->sock, buf, (int)rd) != 0)
            return;
    }
